export function deepThinkingOptions(value) {
  if (value === undefined) return {};
  if (typeof value !== 'object' || value === null || Array.isArray(value)) throw new TypeError('Invalid input type');
  const keys = Object.getOwnPropertyNames(value);
  if (keys.length !== 1 || !['enabled', 'disabled'].includes(value[keys[0]])) throw new TypeError('Invalid input structure or value');
  if (keys[0] !== 'type') throw new TypeError('Invalid key name');
  return { thinking: { type: value.type } };
}
```

